#define _POSIX_C_SOURCE 200809L
#include <ctype.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define TM 20000
#define NM 20000
#define VM 512
#define SZ 4096
#define STEPS 1000000
typedef enum{EOF_T,ID,NUM,STR,LET,IF,ELSE,WHILE,TRUE_T,FALSE_T,LP,RP,LB,RB,SEMI,PLUS,MINUS,STAR,SLASH,EQ,EQEQ,NEQ,LT,LTE,GT,GTE,BANG,AND,OR}K;
typedef struct{K k;char s[SZ];int line;}Tok;static Tok ts[TM];static int nt,at,errors;static const char*file="<source>";
static void err(int l,const char*m){fprintf(stderr,"%s:%d: error: %s\n",file,l,m);errors++;}
static Tok*pk(void){return &ts[at<nt?at:nt-1];}static Tok*pr(void){return &ts[at?at-1:0];}static bool end(void){return pk()->k==EOF_T;}static bool match(K k){if(pk()->k!=k)return false;at++;return true;}
static Tok*take(K k,const char*m){if(pk()->k==k)return &ts[at++];err(pk()->line,m);return pk();}
static void emit(K k,const char*s,size_t n,int l){if(nt>=TM-1){err(l,"token limit exceeded");return;}Tok*t=&ts[nt++];t->k=k;t->line=l;if(n>=SZ)n=SZ-1;memcpy(t->s,s,n);t->s[n]=0;}
static K keyword(const char*s){if(!strcmp(s,"let"))return LET;if(!strcmp(s,"if"))return IF;if(!strcmp(s,"else"))return ELSE;if(!strcmp(s,"while"))return WHILE;if(!strcmp(s,"true"))return TRUE_T;if(!strcmp(s,"false"))return FALSE_T;return ID;}
static void lex(const char*s){size_t i=0;int l=1;while(s[i]&&nt<TM-1){char x=s[i];if(x==' '||x=='\r'||x=='\t'){i++;continue;}if(x=='\n'){l++;i++;continue;}if(x=='/'&&s[i+1]=='/'){while(s[i]&&s[i]!='\n')i++;continue;}
if(isalpha((unsigned char)x)||x=='_'){size_t b=i++;while(isalnum((unsigned char)s[i])||s[i]=='_')i++;char w[SZ];size_t n=i-b;if(n>=SZ)n=SZ-1;memcpy(w,s+b,n);w[n]=0;emit(keyword(w),w,n,l);continue;}
if(isdigit((unsigned char)x)){size_t b=i++;while(isdigit((unsigned char)s[i]))i++;emit(NUM,s+b,i-b,l);continue;}
if(x=='"'){int start=l;i++;char b[SZ];size_t n=0;while(s[i]&&s[i]!='"'){char q=s[i++];if(q=='\n')l++;if(q=='\\'&&s[i]){char e=s[i++];q=e=='n'?'\n':e=='t'?'\t':e=='r'?'\r':e;}if(n<SZ-1)b[n++]=q;}if(!s[i])err(start,"unterminated string");else i++;b[n]=0;emit(STR,b,n,start);continue;}
K k=EOF_T;size_t n=1;switch(x){case '(':k=LP;break;case ')':k=RP;break;case '{':k=LB;break;case '}':k=RB;break;case ';':k=SEMI;break;case '+':k=PLUS;break;case '-':k=MINUS;break;case '*':k=STAR;break;case '/':k=SLASH;break;case '!':if(s[i+1]=='='){k=NEQ;n=2;}else k=BANG;break;case '=':if(s[i+1]=='='){k=EQEQ;n=2;}else k=EQ;break;case '<':if(s[i+1]=='='){k=LTE;n=2;}else k=LT;break;case '>':if(s[i+1]=='='){k=GTE;n=2;}else k=GT;break;case '&':if(s[i+1]=='&'){k=AND;n=2;}break;case '|':if(s[i+1]=='|'){k=OR;n=2;}break;}if(k==EOF_T){char m[80];snprintf(m,sizeof m,"unexpected character '%c'",x);err(l,m);i++;continue;}emit(k,s+i,n,l);i+=n;}emit(EOF_T,"",0,l);}
typedef enum{LN,LS,LBV,V,BIN,UN,CALL,DECL,SET,EXPR,BLOCK,IFN,WHILEN}NK;typedef struct N N;struct N{NK k;int line;char s[SZ];long num;bool bv;N*a,*b,*c,*next;};static N ns[NM];static int nn;
static N*mk(NK k,int l){if(nn>=NM){err(l,"AST node limit exceeded");return &ns[NM-1];}N*n=&ns[nn++];memset(n,0,sizeof *n);n->k=k;n->line=l;return n;}static N*expression(void);static N*statement(void);
static N*primary(void){Tok*t=pk();if(match(NUM)){N*n=mk(LN,t->line);n->num=strtol(t->s,0,10);return n;}if(match(STR)){N*n=mk(LS,t->line);strcpy(n->s,t->s);return n;}if(match(TRUE_T)||match(FALSE_T)){N*n=mk(LBV,t->line);n->bv=t->k==TRUE_T;return n;}if(match(ID)){if(match(LP)){N*n=mk(CALL,t->line);strcpy(n->s,t->s);if(pk()->k!=RP)n->a=expression();take(RP,"expected ')'");return n;}N*n=mk(V,t->line);strcpy(n->s,t->s);return n;}if(match(LP)){N*n=expression();take(RP,"expected ')'");return n;}err(t->line,"expected expression");if(!end())at++;return mk(LN,t->line);}
static N*unary(void){if(match(BANG)||match(MINUS)){Tok*t=pr();N*n=mk(UN,t->line);strcpy(n->s,t->k==BANG?"!":"-");n->a=unary();return n;}return primary();}
static N*factor(void){N*n=unary();while(pk()->k==STAR||pk()->k==SLASH){Tok*t=pk();at++;N*r=mk(BIN,t->line);strcpy(r->s,t->s);r->a=n;r->b=unary();n=r;}return n;}
static N*term(void){N*n=factor();while(pk()->k==PLUS||pk()->k==MINUS){Tok*t=pk();at++;N*r=mk(BIN,t->line);strcpy(r->s,t->s);r->a=n;r->b=factor();n=r;}return n;}
static N*compare(void){N*n=term();while(pk()->k==LT||pk()->k==LTE||pk()->k==GT||pk()->k==GTE){Tok*t=pk();at++;N*r=mk(BIN,t->line);strcpy(r->s,t->s);r->a=n;r->b=term();n=r;}return n;}
static N*equality(void){N*n=compare();while(pk()->k==EQEQ||pk()->k==NEQ){Tok*t=pk();at++;N*r=mk(BIN,t->line);strcpy(r->s,t->s);r->a=n;r->b=compare();n=r;}return n;}
static N*land(void){N*n=equality();while(match(AND)){N*r=mk(BIN,pr()->line);strcpy(r->s,"&&");r->a=n;r->b=equality();n=r;}return n;}
static N*expression(void){N*n=land();while(match(OR)){N*r=mk(BIN,pr()->line);strcpy(r->s,"||");r->a=n;r->b=land();n=r;}return n;}
static N*block(void){N*f=0,*last=0;while(!end()&&pk()->k!=RB){int old=at;N*n=statement();if(n){if(!f)f=n;else last->next=n;last=n;}if(at==old)at++;}take(RB,"expected '}'");return f;}
static N*statement(void){Tok*t=pk();if(match(LET)){Tok*name=take(ID,"expected variable name");take(EQ,"expected '='");N*n=mk(DECL,t->line);strcpy(n->s,name->s);n->a=expression();take(SEMI,"expected ';'");return n;}if(match(IF)){N*n=mk(IFN,t->line);take(LP,"expected '('");n->a=expression();take(RP,"expected ')'");take(LB,"expected '{'");n->b=mk(BLOCK,t->line);n->b->a=block();if(match(ELSE)){take(LB,"expected '{'");n->c=mk(BLOCK,t->line);n->c->a=block();}return n;}if(match(WHILE)){N*n=mk(WHILEN,t->line);take(LP,"expected '('");n->a=expression();take(RP,"expected ')'");take(LB,"expected '{'");n->b=mk(BLOCK,t->line);n->b->a=block();return n;}if(match(LB)){N*n=mk(BLOCK,t->line);n->a=block();return n;}if(t->k==ID&&at+1<nt&&ts[at+1].k==EQ){at+=2;N*n=mk(SET,t->line);strcpy(n->s,t->s);n->a=expression();take(SEMI,"expected ';'");return n;}if(end())return 0;N*e=expression();take(SEMI,"expected ';'");N*n=mk(EXPR,t->line);n->a=e;return n;}
static N*parse(void){N*f=0,*last=0;while(!end()){int old=at;N*n=statement();if(n){if(!f)f=n;else last->next=n;last=n;}if(at==old)at++;}return f;}
typedef enum{NULLV,NUMV,STRV,BOOLV}VK;typedef struct{VK k;long num;bool bv;char*s;}Val;static Val nullv(void){Val v={.k=NULLV};return v;}static Val numv(long x){Val v={.k=NUMV,.num=x};return v;}static Val boolv(bool x){Val v={.k=BOOLV,.bv=x};return v;}static Val strv(const char*s){Val v={.k=STRV,.s=strdup(s?s:"")};if(!v.s){perror("strdup");exit(2);}return v;}
static char*display(Val v,char*b,size_t z){if(v.k==STRV)return v.s;if(v.k==NUMV)snprintf(b,z,"%ld",v.num);else if(v.k==BOOLV)snprintf(b,z,"%s",v.bv?"true":"false");else snprintf(b,z,"null");return b;}static bool truth(Val v){return v.k==BOOLV?v.bv:v.k==NUMV?v.num!=0:v.k==STRV&&v.s&&*v.s;}
typedef struct{char name[SZ];Val v;}Binding;static Binding vars[VM];static int nv;static long steps;static int find(const char*s){for(int i=0;i<nv;i++)if(!strcmp(vars[i].name,s))return i;return -1;}
static void setvar(const char*s,Val v,int l,bool decl){int i=find(s);if(i<0){if(!decl){err(l,"assignment to undeclared variable");return;}if(nv==VM){err(l,"variable limit exceeded");return;}i=nv++;strncpy(vars[i].name,s,SZ-1);}vars[i].v=v;}
static Val eval(N*n){if(!n)return nullv();switch(n->k){case LN:return numv(n->num);case LS:return strv(n->s);case LBV:return boolv(n->bv);case V:{int i=find(n->s);if(i<0){err(n->line,"unknown variable");return nullv();}return vars[i].v;}case CALL:if(!strcmp(n->s,"input")){Val p=n->a?eval(n->a):strv("");char b[SZ],line[SZ];fputs(display(p,b,sizeof b),stdout);fflush(stdout);if(!fgets(line,sizeof line,stdin))line[0]=0;line[strcspn(line,"\r\n")]=0;return strv(line);}if(!strcmp(n->s,"print")){Val v=n->a?eval(n->a):nullv();char b[SZ];puts(display(v,b,sizeof b));return nullv();}err(n->line,"unknown built-in");return nullv();case UN:{Val a=eval(n->a);if(!strcmp(n->s,"!"))return boolv(!truth(a));if(a.k!=NUMV){err(n->line,"unary minus requires number");return numv(0);}return numv(-a.num);}case BIN:{Val a=eval(n->a);if(!strcmp(n->s,"&&")&&!truth(a))return boolv(false);if(!strcmp(n->s,"||")&&truth(a))return boolv(true);Val b=eval(n->b);if(!strcmp(n->s,"&&"))return boolv(truth(a)&&truth(b));if(!strcmp(n->s,"||"))return boolv(truth(a)||truth(b));if(!strcmp(n->s,"+")){if(a.k==STRV||b.k==STRV){char x[SZ],y[SZ],z[SZ];snprintf(z,sizeof z,"%s%s",display(a,x,sizeof x),display(b,y,sizeof y));return strv(z);}if(a.k==NUMV&&b.k==NUMV)return numv(a.num+b.num);}if(!strcmp(n->s,"==")||!strcmp(n->s,"!=")){bool eq=false;if(a.k==STRV&&b.k==STRV)eq=!strcmp(a.s,b.s);else if(a.k==NUMV&&b.k==NUMV)eq=a.num==b.num;else if(a.k==BOOLV&&b.k==BOOLV)eq=a.bv==b.bv;else eq=a.k==b.k;return boolv(!strcmp(n->s,"==")?eq:!eq);}if(a.k!=NUMV||b.k!=NUMV){err(n->line,"operator requires numbers");return numv(0);}if(!strcmp(n->s,"-"))return numv(a.num-b.num);if(!strcmp(n->s,"*"))return numv(a.num*b.num);if(!strcmp(n->s,"/")){if(!b.num){err(n->line,"division by zero");return numv(0);}return numv(a.num/b.num);}if(!strcmp(n->s,"<"))return boolv(a.num<b.num);if(!strcmp(n->s,"<="))return boolv(a.num<=b.num);if(!strcmp(n->s,">"))return boolv(a.num>b.num);if(!strcmp(n->s,">="))return boolv(a.num>=b.num);break;}default:break;}return nullv();}
static void run(N*n){for(;n&&!errors;n=n->next){if(++steps>STEPS){err(n->line,"execution step limit exceeded");return;}switch(n->k){case DECL:setvar(n->s,eval(n->a),n->line,true);break;case SET:setvar(n->s,eval(n->a),n->line,false);break;case EXPR:(void)eval(n->a);break;case BLOCK:run(n->a);break;case IFN:run(truth(eval(n->a))?n->b:n->c);break;case WHILEN:while(truth(eval(n->a))&&!errors){if(++steps>STEPS){err(n->line,"execution step limit exceeded");break;}run(n->b->a);}break;default:err(n->line,"invalid statement");break;}}}
static char*load(const char*p){FILE*f=fopen(p,"rb");if(!f){perror(p);return 0;}if(fseek(f,0,SEEK_END)){fclose(f);return 0;}long n=ftell(f);if(n<0||n>1024*1024){fclose(f);fprintf(stderr,"source file too large\n");return 0;}rewind(f);char*s=malloc((size_t)n+1);if(!s){fclose(f);return 0;}size_t got=fread(s,1,(size_t)n,f);fclose(f);s[got]=0;return s;}
int main(int argc,char**argv){if(argc!=2){fprintf(stderr,"Usage: vnx <program.vnx>\n");return 2;}file=argv[1];char*s=load(argv[1]);if(!s)return 2;lex(s);N*p=errors?0:parse();if(!errors)run(p);free(s);return errors?1:0;}
